VALUES ('ffaed9e0-0b6b-5c9f-8d06-25494bb02835', 1, '{"questions":[{"id":"51d1215f-638d-5cec-a87c-c511d730bfa3","dimension":"EI","rightPole":"E","statement":"[PET_NAME] ALWAYS… acts like they''ve had 17 cups of coffee","shareQuote":"[PET_NAME] operates at approximately 400% capacity at all times. The vet has no explanation.","visualBrief":"Pet bouncing off walls with cartoon lightning bolts","imagePublicId":null},{"id":"66ee0d44-b80e-5776-80ae-b238bcca1790","dimension":"EI","rightPole":"I","statement":"[PET_NAME] NEVER… says no to a nap opportunity","shareQuote":"[PET_NAME] treats sleep as a competitive sport and is currently ranked number one.","visualBrief":"Pet sleeping in increasingly creative and impractical positions","imagePublicId":null},{"id":"2c3fa635-1da2-5cd6-965c-7bba5d8a8cb4","dimension":"EI","rightPole":"E","statement":"[PET_NAME] ALWAYS… gets excited about the word ''walk'' (even when spelled out)","shareQuote":"I cannot spell w-a-l-k in my own home. We have had to develop a code.","visualBrief":"Pet doing full parkour lap of the house at the mere mention of outdoor activity","imagePublicId":null},{"id":"4018db14-8b35-59a3-a185-3798b3f68a72","dimension":"EI","rightPole":"E","statement":"[PET_NAME] NEVER… seems to run out of energy","shareQuote":"I am tired. My pet is not. This has been the situation for three years.","visualBrief":"Pet still bouncing joyfully while three humans lie exhausted on the floor behind them","imagePublicId":null},{"id":"597bf684-6d12-53e3-b42e-9f01366454f4","dimension":"SN","rightPole":"S","statement":"[PET_NAME] ALWAYS… thinks every human exists specifically to pet them","shareQuote":"[PET_NAME] believes they are universally beloved. They may be correct.","visualBrief":"Pet doing full-body wiggle approach toward complete stranger, absolutely certain of welcome","imagePublicId":null},{"id":"e1dbddbf-0b5c-5633-8799-36df7ad859b4","dimension":"SN","rightPole":"S","statement":"[PET_NAME] ALWAYS… appears instantly when they hear someone upset","shareQuote":"[PET_NAME] is an uncertified emotional support professional who waived the fee.","visualBrief":"Pet materialising with concerned expression from nowhere at precisely the right moment","imagePublicId":null},{"id":"d34a1cd4-8e46-56ed-b953-251fc67ddfe1","dimension":"SN","rightPole":"N","statement":"[PET_NAME] NEVER… seems to need constant attention from humans","shareQuote":"[PET_NAME] is fine without me. I am not fine without them. The power imbalance is real.","visualBrief":"Pet serenely doing their own thing while human desperately tries to get their attention","imagePublicId":null},{"id":"760f3449-ff86-5e34-b56e-11661daa1d0f","dimension":"TF","rightPole":"T","statement":"[PET_NAME] ALWAYS… learns new things suspiciously quickly","shareQuote":"[PET_NAME] understands everything I say and selectively chooses when to act on it.","visualBrief":"Pet nailing a trick first attempt while maintaining look of absolute nonchalance","imagePublicId":null},{"id":"40927919-eb65-51d5-ae3b-64f34acd9e42","dimension":"TF","rightPole":"F","statement":"[PET_NAME] NEVER… does something just because I asked them to","shareQuote":"[PET_NAME] heard me. My pet considered it. My pet decided against it. Respectfully.","visualBrief":"Pet receiving clear command, considering it, making firm eye contact, and doing something completely different","imagePublicId":null},{"id":"cb212b41-2062-5be1-8b54-b78ded584f10","dimension":"TF","rightPole":"T","statement":"[PET_NAME] ALWAYS… comes when called (eventually)","shareQuote":"[PET_NAME] responds to their name on their own timeline. We respect the timeline.","visualBrief":"Pet doing a very casual slow-walk response to their name, three to five business days later","imagePublicId":null},{"id":"e4d2fead-e1a9-593a-a7e9-b64a936cad3e","dimension":"TF","rightPole":"F","statement":"[PET_NAME] NEVER… follows the rules when they clearly know what the rules are","shareQuote":"[PET_NAME] knows the rules. My pet has opinions about the rules. The rules are suggestions.","visualBrief":"Pet maintaining eye contact while committing the exact infraction they have been informed is not allowed","imagePublicId":null},{"id":"6566ee46-bb1b-5cff-a040-cc004081bc38","dimension":"BC","rightPole":"B","statement":"[PET_NAME] ALWAYS… is the first to investigate strange noises","shareQuote":"[PET_NAME] is the home''s first responder. Brave, fast, occasionally correct.","visualBrief":"Pet confidently striding toward mysterious sounds while every other creature hides behind the human","imagePublicId":null},{"id":"809819ad-78d6-5eb5-ba5a-56b05809a4f4","dimension":"BC","rightPole":"C","statement":"[PET_NAME] NEVER… goes anywhere without checking if I''m coming too","shareQuote":"[PET_NAME] needs emotional support to cross a threshold. I am their emotional support human.","visualBrief":"Pet looking back anxiously for explicit human approval before proceeding each approximately fifteen centimetres","imagePublicId":null},{"id":"e68d727e-4208-5d00-9532-c65e39d295eb","dimension":"BC","rightPole":"B","statement":"[PET_NAME] ALWAYS… treats new experiences like personal challenges to conquer","shareQuote":"[PET_NAME] has never met a new situation they didn''t immediately try to dominate.","visualBrief":"Pet approaching completely new object with determined expression and absolute confidence in the outcome","imagePublicId":null},{"id":"0381e1a2-6ee0-56e9-9b67-c81efc3f5c08","dimension":"BC","rightPole":"B","statement":"[PET_NAME] NEVER… seems fazed by anything life throws at them","shareQuote":"[PET_NAME] is the most mentally stable individual in this household. The bar is low. They clear it.","visualBrief":"Pet sitting calmly at the centre of total domestic chaos — vacuums, fireworks, builders — completely unbothered","imagePublicId":null},{"id":"a09d2589-4f66-52c5-8ca2-3f0736588ea5","dimension":"EI","rightPole":"I","statement":"[PET_NAME] ALWAYS… lies down mid-walk to announce the walk is over","shareQuote":"Halfway round the park, [PET_NAME] staged a sit-in. The walk ended there.","visualBrief":"Dog flat out on the pavement, lead slack, owner looking at their watch","imagePublicId":null},{"id":"a97270b8-8b8e-524c-98fd-43373ea8d239","dimension":"SN","rightPole":"N","statement":"[PET_NAME] ALWAYS… takes themselves off to bed when guests stay too long","shareQuote":"[PET_NAME] left the party at 9pm. Honestly, I was jealous.","visualBrief":"Dog padding upstairs past a dinner party in full swing","imagePublicId":null},{"id":"6cb08271-f9ba-5505-9286-25b226db4e9e","dimension":"SN","rightPole":"S","statement":"[PET_NAME] NEVER… lets a visitor sit down without a proper welcome","shareQuote":"Every guest gets the VIP treatment. The postman included.","visualBrief":"Dog greeting a guest on the sofa with a full-body wiggle and a slipper offering","imagePublicId":null},{"id":"f752e9a7-561b-5864-afb6-243da14b4853","dimension":"TF","rightPole":"T","statement":"[PET_NAME] ALWAYS… sits before being asked whenever a treat appears","shareQuote":"[PET_NAME] has worked out the system and is gaming it beautifully.","visualBrief":"Dog in a perfect sit, staring at a biscuit tin, owner not yet looking","imagePublicId":null},{"id":"6f3e6e7c-827f-50ff-8264-906fd8e7b541","dimension":"BC","rightPole":"C","statement":"[PET_NAME] ALWAYS… gives anything new a very wide berth for at least a day","shareQuote":"A new bin arrived on Tuesday. We''re still in negotiations.","visualBrief":"Dog peering round a doorframe at a new wheelie bin","imagePublicId":null}],"resultTypes":[{"code":"ESTB","name":"The Golden Retriever","tagline":"The Eternal Optimist","traits":["Boundlessly enthusiastic — loves everyone, treats every day like the best day ever"],"signatureMove":"Full-body wiggle greeting for every human regardless of familiarity","ownerReality":"Your pet thinks every stranger is their new best friend","shareQuote":"[PET_NAME] is 90% enthusiasm, 10% actual dog. The enthusiasm is non-negotiable.","designImageId":null},{"code":"ESTC","name":"The Gentle Giant","tagline":"The Careful Optimist","traits":["Happy and social but reads the room first"],"signatureMove":"Enthusiastic tail wag from a polite, considerate distance","ownerReality":"Your pet is the friend who brings good vibes to every situation without overwhelming anyone","shareQuote":"[PET_NAME] is the emotionally intelligent one in this relationship. It shows.","designImageId":null},{"code":"ESFB","name":"The Party Animal","tagline":"The Social Anarchist","traits":["First to every activity, last to leave, not sure what ''quiet time'' means"],"signatureMove":"Launching into play mode without any warm-up whatsoever","ownerReality":"Your pet is the chaos that makes life interesting","shareQuote":"[PET_NAME] doesn''t do ''calm''. We''ve accepted this. We''re at peace with it.","designImageId":null},{"code":"ESFC","name":"The Self-Appointed Supervisor","tagline":"The Eager Assistant","traits":["Sociable and always involved, but on their own terms and from a safe distance"],"signatureMove":"Inserting themselves into every household task with maximum enthusiasm","ownerReality":"Your pet is always busy and none of it is your business","shareQuote":"[PET_NAME] helps with everything. Most of it unhelpfully. All of it enthusiastically.","designImageId":null},{"code":"ENTB","name":"The Action Hero","tagline":"The Self-Starter","traits":["High energy, happy with or without company, learns fast and tries anything once"],"signatureMove":"Finding the one thing in the house they''re not supposed to touch","ownerReality":"Your pet is exhausting, incredible, and has no regrets","shareQuote":"[PET_NAME] makes their own rules. I consult them before making any decisions.","designImageId":null},{"code":"ENTC","name":"The Social Philosopher","tagline":"The Curious Connector","traits":["Social and enquiring — they need to understand everything before committing"],"signatureMove":"Sitting very close and staring with intense intellectual curiosity","ownerReality":"Your pet is conducting research on you. Continuously.","shareQuote":"[PET_NAME] is studying me. I believe I am passing. The criteria are unclear.","designImageId":null},{"code":"ENFB","name":"The Wild Card","tagline":"The Unpredictable Force","traits":["Energetic, independent, free-spirited and bold: the most unpredictable combination"],"signatureMove":"Doing the unexpected in every situation without exception","ownerReality":"You never know what''s coming. That''s the whole experience.","shareQuote":"[PET_NAME] is a one-of-a-kind chaos engine and I would not change a single thing.","designImageId":null},{"code":"ENFC","name":"The Gentle Storm","tagline":"The Warm Adventurer","traits":["High energy and happy doing their own thing, but takes anything new very slowly"],"signatureMove":"Enthusiastic participation once they''ve determined it''s safe","ownerReality":"Your pet is brave on their own timeline. The timeline is theirs.","shareQuote":"[PET_NAME]''s bravery is selective and deliberate. I respect the system.","designImageId":null},{"code":"ISTB","name":"The Loyal Guardian","tagline":"The Steady Protector","traits":["Calm confidence, always watching over their family"],"signatureMove":"Quietly positioning themselves between family and any potential threat","ownerReality":"Your pet is the strong, silent type who takes their responsibilities seriously","shareQuote":"My dog doesn''t need to bark to communicate that they are on duty. They are always on duty.","designImageId":null},{"code":"ISTC","name":"The Gentle Soul","tagline":"The Quiet Companion","traits":["Prefers peaceful moments — excellent judge of character and atmosphere"],"signatureMove":"Slow, deliberate approach with a cautious tail wag","ownerReality":"Your pet is the friend who shows up with everything you need before you ask for it","shareQuote":"[PET_NAME] believes the best conversations happen in comfortable silence. They''re right.","designImageId":null},{"code":"ISFB","name":"The Confident Couch Potato","tagline":"The Regal Relaxer","traits":["Dignified presence — social but entirely on their own terms and schedule"],"signatureMove":"Graciously accepting attention from their throne, which is your sofa","ownerReality":"Your pet has mastered looking majestic while doing absolutely nothing","shareQuote":"[PET_NAME] believes they are royalty. Honestly, they''re not wrong.","designImageId":null},{"code":"ISFC","name":"The Velcro Pet","tagline":"The Professional Snuggler","traits":["Lives for quiet bonding time — perfectly content just being near you"],"signatureMove":"Slowly migrating closer during quiet time until they are technically on your lap","ownerReality":"Your pet has redefined personal space to mean shared space","shareQuote":"[PET_NAME]''s favourite hobby is being as close to me as physically possible. I don''t mind.","designImageId":null},{"code":"INTB","name":"The Wise Observer","tagline":"The Silent Strategist","traits":["Highly intelligent — prefers to watch and learn before acting"],"signatureMove":"Solving problems through careful observation that makes humans feel slightly watched","ownerReality":"Your pet is definitely smarter than most humans you know","shareQuote":"[PET_NAME] has figured out things about this household that I haven''t noticed yet.","designImageId":null},{"code":"INTC","name":"The Peaceful Philosopher","tagline":"The Zen Master","traits":["Deeply contemplative — finds wisdom in quiet moments"],"signatureMove":"Long, thoughtful gazes that appear to contain the secrets of the universe","ownerReality":"Your pet has achieved a level of inner peace that you can only aspire to","shareQuote":"[PET_NAME] could teach a masterclass in equanimity. I would attend. I would take notes.","designImageId":null},{"code":"INFB","name":"The Creative Rebel","tagline":"The Artistic Soul","traits":["Marches to their own beat — finds creative solutions to every situation"],"signatureMove":"Turning completely ordinary objects into sources of personal entertainment","ownerReality":"Your pet sees the world as their personal creative project","shareQuote":"[PET_NAME] believes rules are starting points for creative interpretation. The results are extraordinary.","designImageId":null},{"code":"INFC","name":"The Mysterious Mystic","tagline":"The Enigmatic Sage","traits":["Deeply independent — shares wisdom sparingly and on their own terms"],"signatureMove":"Appearing and disappearing with timing that seems genuinely supernatural","ownerReality":"Your pet knows things. They will never tell you.","shareQuote":"[PET_NAME] chooses when to grace me with their presence. I am honoured every time.","designImageId":null}]}'::jsonb)
ON CONFLICT (quiz_id, version) DO NOTHING;

