INSERT INTO public.quiz_versions (quiz_id, version, content)
VALUES ('429e1106-b96b-58f2-be32-98fe2dc1b952', 1, '{"questions":[{"id":"ff318238-a3d5-5420-8281-18b3d1cc390a","dimension":"EI","rightPole":"E","statement":"[PET_NAME] ALWAYS… does a full-speed lap of the house at 3am","shareQuote":"Every night at 3am [PET_NAME] hosts a Grand Prix. I am the track.","visualBrief":"Cat mid-skid round a corner in a dark hallway, owner''s door ajar","imagePublicId":null},{"id":"194e9b80-fa7e-509e-a067-756bec5a7e14","dimension":"EI","rightPole":"I","statement":"[PET_NAME] NEVER… turns down a sunny spot for a nap","shareQuote":"[PET_NAME] follows the sun round the house like a very small solar panel.","visualBrief":"Cat stretched along a single strip of sunlight on the floorboards","imagePublicId":null},{"id":"3b3a6722-9721-546a-a91c-bf5652f4198c","dimension":"EI","rightPole":"E","statement":"[PET_NAME] ALWAYS… stalks, pounces and wins whenever a toy moves","shareQuote":"The feather wand hasn''t won a round in four years.","visualBrief":"Cat airborne, all four paws out, feather wand bent in defeat","imagePublicId":null},{"id":"7848eace-3e56-5709-824e-99bc881c91a2","dimension":"EI","rightPole":"I","statement":"[PET_NAME] ALWAYS… watches me wave a toy about, then looks at me with pity","shareQuote":"I perform. [PET_NAME] reviews. The reviews are poor.","visualBrief":"Cat lying still, unimpressed, while the owner flails a toy mouse","imagePublicId":null},{"id":"74fe341f-156b-54e7-b99b-d3e6f782fddd","dimension":"EI","rightPole":"E","statement":"[PET_NAME] NEVER… stays still long enough for a decent photo","shareQuote":"My camera roll is 400 blurry photos of a tail.","visualBrief":"Phone screen showing a blurry streak of tail","imagePublicId":null},{"id":"52d403d7-e70d-5c69-a6cf-bbe08e3b0906","dimension":"SN","rightPole":"S","statement":"[PET_NAME] ALWAYS… comes to the door to inspect every visitor","shareQuote":"[PET_NAME] runs the guest list. Most people get in.","visualBrief":"Cat sitting on the doormat looking a guest up and down like a bouncer","imagePublicId":null},{"id":"3736b9e4-7e13-5a25-aec8-a19d74d49134","dimension":"SN","rightPole":"S","statement":"[PET_NAME] NEVER… lets me sit down without claiming my lap","shareQuote":"I haven''t seen my own lap since 2022.","visualBrief":"Cat already circling on the owner''s lap before they''ve finished sitting","imagePublicId":null},{"id":"e0a2228b-89af-5ad9-999d-7a9b5f013ac8","dimension":"SN","rightPole":"N","statement":"[PET_NAME] ALWAYS… likes company, as long as it''s in the next room","shareQuote":"[PET_NAME] enjoys our company from a respectful distance.","visualBrief":"Cat on a chair in the hallway, glancing through the doorway at the family","imagePublicId":null},{"id":"c895f085-bc53-507a-b7c0-d76222382060","dimension":"SN","rightPole":"S","statement":"[PET_NAME] ALWAYS… follows me from room to room to supervise","shareQuote":"I can''t open a cupboard without an inspector present.","visualBrief":"Cat sitting on the bathroom mat staring at the owner","imagePublicId":null},{"id":"d1e62598-02cb-5444-8315-6b1d18dd8cf3","dimension":"SN","rightPole":"N","statement":"[PET_NAME] NEVER… asks for a cuddle; cuddles are by appointment","shareQuote":"Cuddles are available on Tuesdays, briefly, on [PET_NAME]''s terms.","visualBrief":"Cat holding up one paw to an owner leaning in for a hug","imagePublicId":null},{"id":"09661b8b-cb1d-588e-bc93-f422cc5e4762","dimension":"TF","rightPole":"T","statement":"[PET_NAME] ALWAYS… comes running at the sound of their name","shareQuote":"[PET_NAME] comes when called. Nobody believes me.","visualBrief":"Cat bounding down the stairs as the owner calls from the kitchen","imagePublicId":null},{"id":"eccf98d3-a42a-54a9-962b-f7fbcfeda4c7","dimension":"TF","rightPole":"F","statement":"[PET_NAME] NEVER… gets off the kitchen counter just because I said so","shareQuote":"I said ''down''. [PET_NAME] heard ''stay exactly where you are''.","visualBrief":"Cat on the worktop beside the butter, holding eye contact","imagePublicId":null},{"id":"f43ecf9d-a3e6-513a-8737-cec6759c88ac","dimension":"TF","rightPole":"T","statement":"[PET_NAME] ALWAYS… knows the routine and turns up for it on the dot","shareQuote":"Breakfast is at 7. [PET_NAME] files a complaint at 6:58.","visualBrief":"Cat sitting by the food bowl, clock on the wall at 6:59","imagePublicId":null},{"id":"c320738e-a8b2-53c1-940c-3bf3ce561a97","dimension":"TF","rightPole":"F","statement":"[PET_NAME] ALWAYS… pushes things off tables while looking straight at me","shareQuote":"[PET_NAME] tests gravity daily. The results haven''t changed.","visualBrief":"Cat mid-nudge, a mug at the table''s edge, eyes on the owner","imagePublicId":null},{"id":"8697f8eb-fdda-5437-b2fa-fdb9ff90ed41","dimension":"TF","rightPole":"T","statement":"[PET_NAME] ALWAYS… stops scratching the sofa when told (for now)","shareQuote":"[PET_NAME] respects the ''no''. The sofa remains cautiously optimistic.","visualBrief":"Cat freezing mid-scratch, one paw still on the sofa arm","imagePublicId":null},{"id":"333278cb-6003-55c5-a09c-d856c7391249","dimension":"BC","rightPole":"B","statement":"[PET_NAME] ALWAYS… climbs into any new box within seconds of it arriving","shareQuote":"We order things online purely for the boxes.","visualBrief":"Cat already in a delivery box, the new kettle still on the floor","imagePublicId":null},{"id":"5a1685f2-2365-5e5a-995d-5c9093331878","dimension":"BC","rightPole":"C","statement":"[PET_NAME] NEVER… comes out until the hoover is back in the cupboard","shareQuote":"The hoover went away an hour ago. [PET_NAME] needs another twenty minutes.","visualBrief":"Two eyes glowing from under the bed, hoover in the doorway","imagePublicId":null},{"id":"b9af1835-c12b-538d-87d2-6b8246c01c61","dimension":"BC","rightPole":"B","statement":"[PET_NAME] ALWAYS… heads straight out to investigate when a door is left open","shareQuote":"[PET_NAME] treats an open door as an invitation to see the world.","visualBrief":"Cat striding across the threshold into the garden like an explorer","imagePublicId":null},{"id":"5d9d60e6-16ea-5572-9258-dd0434d5b7c5","dimension":"BC","rightPole":"C","statement":"[PET_NAME] ALWAYS… needs a full day to forgive a trip in the carrier","shareQuote":"One vet visit, three days of silence. Message received.","visualBrief":"Cat facing the wall, back to the owner, empty carrier by the door","imagePublicId":null},{"id":"e063eabf-4468-52ad-982d-096200915a2b","dimension":"BC","rightPole":"B","statement":"[PET_NAME] NEVER… lets a passing dog spoil their afternoon","shareQuote":"[PET_NAME] once stared down a Rottweiler. The Rottweiler left.","visualBrief":"Cat sitting calmly on a garden wall while a large dog barks below","imagePublicId":null}],"resultTypes":[{"code":"ESTB","name":"The Welcoming Committee","tagline":"The Feline Greeter","traits":["Lively, sociable and quick to answer when called — first to the door, first to the box"],"signatureMove":"Meeting guests at the door and escorting them to the sofa","ownerReality":"Your cat thinks every visitor came to see them. Usually correct.","shareQuote":"[PET_NAME] greets visitors before I do. I''m the support act.","designImageId":null},{"code":"ESTC","name":"The Devoted Sidekick","tagline":"The Gentle Shadow","traits":["Busy and affectionate, sticks to your routine, wary of anything new"],"signatureMove":"Following one step behind, room to room","ownerReality":"Your cat goes where you go, unless something has changed.","shareQuote":"[PET_NAME] goes everywhere I go. Unless there''s a new rug.","designImageId":null},{"code":"ESFB","name":"The Household Tornado","tagline":"The Fearless Freelancer","traits":["All energy, loves an audience, ignores the rules and fears nothing"],"signatureMove":"The 3am lap that ends on your face","ownerReality":"Your cat runs the house. You''re allowed to live here.","shareQuote":"[PET_NAME] runs this house. I just pay the bills.","designImageId":null},{"code":"ESFC","name":"The Chatty Diva","tagline":"The Opinionated Socialite","traits